INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 6, 'theory', 'UDP and Sockets: Datagrams Without Guarantees');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 6, 0, 'What exactly does the UDP header add to the data?', '["Sequence and acknowledgment numbers", "Sender and receiver addresses", "Receive window and connection flags", "Source port, destination port, length, and checksum"]', 3, 'The whole UDP header is 8 bytes: four fields of 2 bytes each.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 6, 1, 'A client sent a datagram to a port where no program listens. What does it get in the best case?', '["An RST from the server", "ICMP \"port unreachable\"", "Nothing: UDP never reports errors", "An automatic retry at the UDP level"]', 1, 'The server may reply with ICMP; but more often there is no reply, and the application relies on a timeout.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 6, 2, 'What is UDP most often chosen for?', '["DNS queries, voice, video, and games, where speed and freshness matter", "Downloading large files without loss", "Sending passwords", "Mail"]', 0, 'It is cheaper to repeat or skip a lost datagram than to keep a connection.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 6, 3, 'What does a simple UDP server do right after binding the socket to a port (bind)?', '["Accepts an incoming connection", "Performs a handshake", "Waits for a datagram with recvfrom", "Closes the socket"]', 2, 'UDP has no connections: the server reads datagrams one by one and replies to the sender.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 6, 4, 'Why do people try to keep UDP datagrams under ~1200 bytes?', '["The standard requires it", "Long datagrams are encrypted more slowly", "Ports run out", "A datagram larger than the MTU is fragmented, and losing any fragment kills the whole datagram"]', 3, 'Short datagrams pass without fragmentation.');
